import { useState, useEffect, useRef } from 'react'

// The power path, in the order energy actually travels. This order is a fact
// about the movement, not a layout decision.
const POWER_PATH = [
  {
    id: 'mainspring',
    name: 'Mainspring',
    detail: 'A 380mm hardened alloy ribbon, wound to 6.5 turns.',
    figure: '72 hours of stored energy at full wind',
  },
  {
    id: 'barrel',
    name: 'Barrel and stop-work',
    detail: 'Releases the spring at a near-constant torque and refuses the last eight per cent, where the rate would drift.',
    figure: 'Torque held within 4% across the run',
  },
  {
    id: 'train',
    name: 'Gear train',
    detail: 'Four wheels step the barrel’s one slow turn up to the escape wheel’s fast one.',
    figure: 'Ratio 1 : 4,608',
  },
  {
    id: 'escapement',
    name: 'Escapement',
    detail: 'A free-sprung lever in silicon releases the train one tooth at a time. This is the ticking.',
    figure: '5 releases per second',
  },
  {
    id: 'balance',
    name: 'Balance wheel',
    detail: 'A 10.6mm glucydur wheel swinging against a flat hairspring. Its period is what the watch calls a second.',
    figure: '18,000 semi-oscillations per hour',
  },
  {
    id: 'hands',
    name: 'Motion work and hands',
    detail: 'The last reduction divides that swing back down into minutes and hours.',
    figure: 'Cumulative deviation −1 to +4 seconds per day',
  },
]

// Physical layers, front of the movement to back. Also a fact, not an order
// chosen for the page.
const LAYERS = [
  { id: 'dial-side', name: 'Dial-side plate', thickness: '0.9mm', mm: 0.9, note: 'Carries the motion work and the hand posts.' },
  { id: 'main', name: 'Main plate', thickness: '1.4mm', mm: 1.4, note: 'German silver, frosted by hand. Every pivot is located from this one surface.' },
  { id: 'bridge', name: 'Train bridge', thickness: '0.8mm', mm: 0.8, note: 'One continuous bridge over all four train wheels, black-polished on the upper flanks.' },
  { id: 'balance-cock', name: 'Balance cock', thickness: '0.7mm', mm: 0.7, note: 'Holds the balance from one side only, so the wheel can be seen turning.' },
]

const CONFIGURATIONS = [
  {
    id: 'frosted',
    name: 'Frosted German silver',
    finish: 'Hand-frosted plates, straight-grained bridges, blued screws.',
    price: 24800,
    lead: 'Delivered from March 2027',
    remaining: 41,
  },
  {
    id: 'skeleton',
    name: 'Open-worked',
    finish: 'Main plate cut back to the load paths, every remaining edge anglaged by hand.',
    price: 39500,
    lead: 'Delivered from September 2027',
    remaining: 12,
  },
  {
    id: 'black',
    name: 'Black-polished steel',
    finish: 'Bridges polished to a true black at every angle, matte plates for contrast.',
    price: 31200,
    lead: 'Delivered from June 2027',
    remaining: 24,
  },
]

const SPECS = [
  ['Reference', 'Caliber 08'],
  ['Diameter', '31.0mm'],
  ['Height', '3.8mm'],
  ['Jewels', '27'],
  ['Frequency', '2.5 Hz (18,000 A/h)'],
  ['Power reserve', '72 hours'],
  ['Regulation', 'Free-sprung, four inertia weights'],
  ['Winding', 'Manual'],
  ['Components', '214'],
  ['Finishing hours', '62 per movement'],
]

const ATELIER = [
  'Designed, cut, and finished at the workshop in Vallée de Joux. Nothing is subcontracted except the jewels and the mainspring.',
  'Eleven watchmakers. Two of them do nothing but finishing.',
  'A total of 200 movements will be made, after which the tooling is retired.',
  'Every movement is run for 21 days in six positions before it leaves. The timing record ships with it.',
  'Serviceable indefinitely. We keep parts for retired calibers and will not stop.',
]

const NAV = [
  ['path', 'Power path'],
  ['construction', 'Construction'],
  ['specification', 'Specification'],
  ['workshop', 'Workshop'],
  ['finishes', 'Finishes'],
]

const chf = (n) => n.toLocaleString('en-CH')

/* Reveals each element once as it enters the viewport. */
function useReveal() {
  useEffect(() => {
    const nodes = document.querySelectorAll('[data-reveal]')
    if (!('IntersectionObserver' in window)) {
      nodes.forEach((n) => n.setAttribute('data-reveal', 'in'))
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.setAttribute('data-reveal', 'in')
            io.unobserve(e.target)
          }
        })
      },
      { rootMargin: '0px 0px -8% 0px', threshold: 0.1 },
    )
    nodes.forEach((n) => io.observe(n))
    return () => io.disconnect()
  }, [])
}

/* The section marker the header shows: which section is currently being read. */
function useCurrentSection() {
  const [current, setCurrent] = useState('')
  useEffect(() => {
    const ids = NAV.map(([id]) => id).concat('reserve')
    const sections = ids.map((id) => document.getElementById(id)).filter(Boolean)
    function onScroll() {
      const line = window.innerHeight * 0.35
      let active = ''
      for (const s of sections) {
        if (s.getBoundingClientRect().top <= line) active = s.id
      }
      setCurrent(active)
    }
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])
  return current
}

/* Decorative balance wheel: turns with scroll, the way the real one is driven. */
function BalanceWheel() {
  const ref = useRef(null)
  useEffect(() => {
    let frame = 0
    function onScroll() {
      if (frame) return
      frame = requestAnimationFrame(() => {
        frame = 0
        const el = ref.current
        if (el) el.style.setProperty('--turn', `${window.scrollY * 0.06}deg`)
      })
    }
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => {
      window.removeEventListener('scroll', onScroll)
      if (frame) cancelAnimationFrame(frame)
    }
  }, [])
  return (
    <svg className="wheel" viewBox="0 0 400 400" aria-hidden="true" focusable="false">
      <defs>
        <radialGradient id="rim" cx="35%" cy="28%">
          <stop offset="0%" stopColor="#d9cfbd" />
          <stop offset="55%" stopColor="#8e8577" />
          <stop offset="100%" stopColor="#4a463f" />
        </radialGradient>
      </defs>
      <g ref={ref} className="wheel-spin">
        <circle cx="200" cy="200" r="150" fill="none" stroke="url(#rim)" strokeWidth="11" />
        <circle cx="200" cy="200" r="150" fill="none" stroke="#0d0d0c" strokeWidth="1" opacity="0.5" />
        {Array.from({ length: 4 }, (_, i) => (
          <circle
            key={i}
            cx={200 + 150 * Math.cos((i * Math.PI) / 2 + Math.PI / 4)}
            cy={200 + 150 * Math.sin((i * Math.PI) / 2 + Math.PI / 4)}
            r="9"
            fill="#c9a227"
            opacity="0.85"
          />
        ))}
        {Array.from({ length: 3 }, (_, i) => (
          <line
            key={i}
            x1={200 + 148 * Math.cos((i * 2 * Math.PI) / 3)}
            y1={200 + 148 * Math.sin((i * 2 * Math.PI) / 3)}
            x2={200 - 148 * Math.cos((i * 2 * Math.PI) / 3)}
            y2={200 - 148 * Math.sin((i * 2 * Math.PI) / 3)}
            stroke="url(#rim)"
            strokeWidth="6"
          />
        ))}
        <circle cx="200" cy="200" r="16" fill="#6f675b" />
        <circle cx="200" cy="200" r="6" fill="#c9a227" />
      </g>
      {/* hairspring */}
      <g className="wheel-spring" opacity="0.5">
        <path
          d={Array.from({ length: 260 }, (_, i) => {
            const t = (i / 259) * 5.6 * Math.PI
            const r = 14 + t * 5.6
            return `${i ? 'L' : 'M'}${(200 + r * Math.cos(t)).toFixed(2)} ${(200 + r * Math.sin(t)).toFixed(2)}`
          }).join(' ')}
          fill="none"
          stroke="#7d93b8"
          strokeWidth="1.4"
        />
      </g>
    </svg>
  )
}

function Header({ current, onReserve }) {
  return (
    <header className="masthead">
      <a className="brand" href="#top">
        <span className="brand-mark" aria-hidden="true">A&amp;V</span>
        <span className="brand-name">Aubry &amp; Vent</span>
      </a>
      <nav className="nav" aria-label="Sections">
        {NAV.map(([id, label]) => (
          <a key={id} href={`#${id}`} aria-current={current === id ? 'true' : undefined}>
            {label}
          </a>
        ))}
      </nav>
      <button type="button" className="btn btn-ghost" onClick={onReserve}>
        Reserve
      </button>
    </header>
  )
}

function Hero() {
  return (
    <section className="hero" id="top">
      <div className="hero-art" aria-hidden="true">
        <BalanceWheel />
      </div>
      <div className="hero-copy">
        <p className="eyebrow">Manual-winding movement · Edition of 200</p>
        <h1 className="display">
          Caliber<span className="numeral"> 08</span>
        </h1>
        <p className="lede">
          A manual-winding mechanical movement, made in a run of 200 and then never again.
        </p>
        <p className="lede-sub">
          Seventy-two hours of stored energy, released one escape-wheel tooth at a time, five times a
          second, for three days from a single wind.
        </p>
        <dl className="keyfigures">
          {[
            ['72 h', 'Power reserve'],
            ['2.5 Hz', 'Frequency'],
            ['3.8 mm', 'Height'],
            ['214', 'Components'],
          ].map(([v, k]) => (
            <div key={k}>
              <dt>{v}</dt>
              <dd>{k}</dd>
            </div>
          ))}
        </dl>
        <a className="btn btn-solid" href="#finishes">
          See the three finishes
        </a>
      </div>
      <div className="hero-rule" aria-hidden="true" />
    </section>
  )
}

function PowerPath() {
  return (
    <section className="section section-path" id="path">
      <div className="section-head" data-reveal>
        <span className="section-index">01</span>
        <h2>How the energy travels</h2>
        <p className="section-note">
          Six stages, in the order the power moves through them — from the wound ribbon to the tip
          of the minute hand.
        </p>
      </div>
      <ol className="path">
        {POWER_PATH.map((s, i) => (
          <li className="stage" key={s.id} data-stage={s.id} data-reveal>
            <div className="stage-rail" aria-hidden="true">
              <span className="stage-num">{String(i + 1).padStart(2, '0')}</span>
            </div>
            <div className="stage-body">
              <h3>{s.name}</h3>
              <p className="stage-detail">{s.detail}</p>
              <p className="stage-figure">{s.figure}.</p>
            </div>
          </li>
        ))}
      </ol>
    </section>
  )
}

function Construction() {
  const total = LAYERS.reduce((a, l) => a + l.mm, 0)
  return (
    <section className="section section-layers" id="construction">
      <div className="section-head" data-reveal>
        <span className="section-index">02</span>
        <h2>Four layers, front to back</h2>
        <p className="section-note">
          The movement is built up in four layers. The bars below are drawn to their true relative
          thickness.
        </p>
      </div>
      <div className="layers">
        {LAYERS.map((l, i) => (
          <article className="layer" key={l.id} data-layer={l.id} data-reveal style={{ '--i': i }}>
            <div className="layer-meta">
              <h3>{l.name}</h3>
              <span className="layer-thickness numeral">{l.thickness}</span>
            </div>
            <div className="layer-bar" aria-hidden="true">
              <span style={{ '--h': `${(l.mm / 1.4) * 100}%` }} />
            </div>
            <p className="layer-note">{l.note}</p>
          </article>
        ))}
      </div>
      <p className="layers-total" data-reveal>
        Stacked height of the plates <span className="numeral">{total.toFixed(1)}mm</span> — the
        finished caliber measures <span className="numeral">3.8mm</span>.
      </p>
    </section>
  )
}

function Specification() {
  return (
    <section className="section section-spec" id="specification">
      <div className="section-head" data-reveal>
        <span className="section-index">03</span>
        <h2>Specification</h2>
      </div>
      <dl className="spec" data-reveal>
        {SPECS.map(([k, v]) => (
          <div className="spec-row" key={k}>
            <dt>{k}</dt>
            <dd className="numeral">{v}</dd>
          </div>
        ))}
      </dl>
    </section>
  )
}

function Workshop() {
  return (
    <section className="section section-workshop" id="workshop">
      <div className="section-head" data-reveal>
        <span className="section-index">04</span>
        <h2>The workshop</h2>
      </div>
      <ul className="atelier">
        {ATELIER.map((a, i) => (
          <li key={a} data-reveal style={{ '--i': i }}>
            <span className="atelier-rule" aria-hidden="true" />
            <p>{a}</p>
          </li>
        ))}
      </ul>
    </section>
  )
}

function Finishes({ config, setConfig }) {
  return (
    <section className="section section-finishes" id="finishes">
      <div className="section-head" data-reveal>
        <span className="section-index">05</span>
        <h2>Three finishes</h2>
        <p className="section-note">
          Prices are for the movement alone; casing is arranged separately.
        </p>
      </div>
      <div className="finishes">
        {CONFIGURATIONS.map((c, i) => {
          const selected = config === c.id
          return (
            <article
              className="finish"
              key={c.id}
              data-config={c.id}
              data-selected={selected || undefined}
              data-reveal
              style={{ '--i': i }}
            >
              <header>
                <h3>{c.name}</h3>
                <p className="finish-desc">{c.finish}</p>
              </header>
              <p className="finish-price numeral">
                <span className="cur">CHF</span> {chf(c.price)}
              </p>
              <dl className="finish-facts">
                <div>
                  <dt>Delivery</dt>
                  <dd>{c.lead}</dd>
                </div>
                <div>
                  <dt>Remaining</dt>
                  <dd>
                    <span className="numeral">{c.remaining}</span> of the run still unallocated
                  </dd>
                </div>
              </dl>
              <div className="finish-gauge" aria-hidden="true">
                <span style={{ '--w': `${(c.remaining / 200) * 100}%` }} />
              </div>
              <button
                type="button"
                className="btn btn-line"
                onClick={() => {
                  setConfig(c.id)
                  document.getElementById('reserve')?.scrollIntoView({ behavior: 'smooth' })
                }}
              >
                {selected ? 'Selected' : 'Choose this finish'}
              </button>
            </article>
          )
        })}
      </div>
    </section>
  )
}

function Reserve({ config, setConfig, chosen }) {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [reserved, setReserved] = useState(false)

  function handleSubmit(e) {
    e.preventDefault()
    if (!name || !email || !config) return
    setReserved(true)
  }

  return (
    <section className="section section-reserve" id="reserve">
      <div className="reserve-card" data-reveal>
        <div className="reserve-intro">
          <span className="section-index">06</span>
          <h2>Reserve a movement</h2>
          <p className="terms">
            Reservations are not binding and no payment is taken now. We will write once, with the
            timing record of the movement allocated to you.
          </p>
        </div>

        {reserved ? (
          <p role="status" className="confirmation">
            <span className="confirm-mark" aria-hidden="true" />
            Reserved. {name}, we have held one {chosen.name} movement at CHF {chf(chosen.price)} and
            will write to {email}. {chosen.lead}.
          </p>
        ) : (
          <form onSubmit={handleSubmit} className="reserve-form">
            <div className="field">
              <label htmlFor="config">Which finish?</label>
              <select
                id="config"
                name="config"
                required
                value={config}
                onChange={(e) => setConfig(e.target.value)}
              >
                <option value="">Choose a finish</option>
                {CONFIGURATIONS.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name} — CHF {chf(c.price)}
                  </option>
                ))}
              </select>
            </div>
            <div className="field">
              <label htmlFor="name">Your name</label>
              <input
                id="name"
                name="name"
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div className="field">
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
            <button type="submit" className="btn btn-solid btn-wide">
              Reserve a movement
            </button>
            {chosen && (
              <p className="reserve-echo">
                {chosen.name} · <span className="numeral">CHF {chf(chosen.price)}</span> ·{' '}
                {chosen.lead}
              </p>
            )}
          </form>
        )}
      </div>
    </section>
  )
}

export default function App() {
  const [config, setConfig] = useState('')
  const chosen = CONFIGURATIONS.find((c) => c.id === config)
  const current = useCurrentSection()
  useReveal()

  return (
    <div className="page">
      <Header
        current={current}
        onReserve={() => document.getElementById('reserve')?.scrollIntoView({ behavior: 'smooth' })}
      />
      <main>
        <Hero />
        <PowerPath />
        <Construction />
        <Specification />
        <Workshop />
        <Finishes config={config} setConfig={setConfig} />
        <Reserve config={config} setConfig={setConfig} chosen={chosen} />
      </main>
      <footer className="footer">
        <div className="footer-row">
          <p className="footer-brand">Aubry &amp; Vent. Caliber 08. © 2026.</p>
          <p>
            Enquiries: <a href="mailto:atelier@aubryvent.ch">atelier@aubryvent.ch</a>
          </p>
        </div>
        <p className="footer-links">
          <span>Servicing.</span> <span>Provenance.</span> <span>Terms of reservation.</span>
        </p>
      </footer>
    </div>
  )
}
